module.exports = /*#__PURE__*/JSON.parse('{"Navigation":{"home":"Home","impressum":"Impressum","privacy":"Privacy Policy","contact":"Contact","language":"Language","terms":"Terms of Use"},"Meta":{"title":"Wildscope: AI Wildlife Identification & Nature Exploration App","description":"Discover and identify wildlife with AI technology, explore nature with offline maps, and track animals like a pro. Your ultimate outdoor companion for wildlife adventures."},"Hero":{"title":"AI-Powered Wildlife Identification & Nature Exploration","subtitle":"Identify plants and animals instantly, track wildlife with precision, and explore nature confidently - even offline. Your complete outdoor companion powered by advanced AI.","feature_1":"AI-Powered Species Recognition & Tracking","feature_2":"Offline Maps & Wildlife Database","feature_3":"Interactive Nature Quizzes & Learning","feature_4":"GPS Navigation & Compass Tools","feature_5":"Text-Based Adventure Mode","feature_6":"Global Wildlife Community","appstore":"Download on App Store","playstore":"Get it on Google Play","download_subtext":"Join thousands of Nature Enthusiasts"},"About":{"title":"Your Complete Wildlife Identification & Nature Guide","paragraph1":"Experience nature like never before with Wildscope\'s advanced AI technology. Whether you\'re identifying plants on a hike, tracking wildlife in remote areas, or learning about local ecosystems, our comprehensive features work seamlessly online and offline.","bullet1":"Instant AI-powered identification of plants, animals, and fungi","bullet2":"Detailed offline maps and species guides for any location","bullet3":"Interactive learning through quizzes and adventure mode","bullet4":"GPS navigation and wildlife tracking tools","bullet5":"Global community of nature enthusiasts","paragraph2":"From casual nature walks to serious wildlife tracking, Wildscope combines cutting-edge AI technology with comprehensive outdoor tools to enhance every nature experience."},"Features":{"title":"Complete Wildlife Identification & Nature Exploration Tools","feature1_title":"Advanced Wildlife Recognition","feature1_desc":"Instantly identify thousands of species with our AI-powered recognition system. Get detailed information about animals, plants, and fungi, including behavior patterns, habitat preferences, and seasonal variations.","feature1_point1":"Real-time species identification with AI","feature1_point2":"Comprehensive wildlife database","feature1_point3":"Seasonal tracking patterns","feature2_title":"Offline Maps & Navigation","feature2_desc":"Never lose your way with our comprehensive offline mapping system. Download regional maps and wildlife data for reliable navigation and species identification, even in remote areas without cell service.","feature2_point1":"Download maps for offline use","feature2_point2":"GPS tracking and waypoints","feature2_point3":"Terrain analysis tools","feature3_title":"Interactive Learning","feature3_desc":"Learn about nature through engaging quizzes, challenges, and our unique text-based adventure mode. Test your knowledge, improve your outdoor skills, and discover new species in your area.","feature3_point1":"Customizable nature quizzes","feature3_point2":"Text-based adventure scenarios","feature3_point3":"Species-specific challenges","feature4_title":"Complete Offline Access","feature4_desc":"Access all essential features without internet connection. Our offline mode includes species data, detailed maps, wildlife guides, and navigation tools - perfect for remote adventures.","feature4_point1":"Full offline functionality","feature4_point2":"Downloadable regional data","feature4_point3":"Offline species guides","feature5_title":"AI Nature Guide","feature5_desc":"Get personalized guidance from our AI nature expert. Ask questions about local wildlife, receive species-specific tips, and learn about ecosystems through natural conversation.","feature5_point1":"24/7 AI nature assistant","feature5_point2":"Contextual wildlife information","feature5_point3":"Personalized learning paths","feature6_title":"Global Wildlife Community","feature6_desc":"Connect with nature enthusiasts worldwide. Share wildlife sightings, discover new locations, and contribute to our growing database of species observations.","feature6_point1":"Share wildlife encounters","feature6_point2":"Discover hotspots","feature6_point3":"Community challenges"},"CallToAction":{"title":"Don\'t Miss Another Amazing Wildlife Moment!","subtitle":"Join thousands of nature enthusiasts who are already discovering and identifying wildlife like never before. Download Wildscope now and transform your outdoor adventures!","appstore":"Get it on App Store","playstore":"Download on Play Store","button":"Start Your Wild Journey","playstoreLink":"https://play.google.com/store/apps/details?id=com.duselk.theoutdoorbible","benefits":["✓ Instant Plant & Animal Identification","✓ Works Offline in Remote Areas","✓ GPS Navigation & Tracking","✓ AI-Powered Nature Guide","✓ Global Wildlife Community"]},"Footer":{"copyright":"© {year} Wildscope. All rights reserved.","impressum":"Impressum","privacy":"Privacy Policy","contact":"Contact"},"CookieBanner":{"message":"This website uses cookies to ensure you get the best experience on our website.","accept":"Accept","decline":"Decline"},"ImpressumPage":{"title":"Legal Notice","section1_title":"Information according to § 5 TMG (German law)","address":"Dustin Keßler<br />Kurt Schumacher Straße 93<br />46539 Dinslaken<br />Germany","contact_title":"Contact","contact_email":"Email: ","responsibility_title":"Responsible for content according to § 55 para. 2 RStV (German law)","disclaimer_title":"Disclaimer","disclaimer_text":"The contents of our site have been created with the utmost care. However, we cannot guarantee the accuracy, completeness, and timeliness of the content. As a service provider, we are responsible for our own content on these pages according to general laws pursuant to § 7 para. 1 TMG (German law). According to §§ 8 to 10 TMG (German law), as a service provider, we are not obliged to monitor transmitted or stored third-party information or to investigate circumstances that indicate illegal activity."},"PrivacyPage":{"content":"# Privacy Policy for Wildscope\\n\\nLast Updated: February 06, 2025\\n\\n## 2. What Data Do We Collect?\\nMost data is stored locally on your device. Data is only stored in the cloud or external services when you use specific features.\\n\\n### 📍 Location & Activity Data\\n• Most location processing occurs locally on your device\\n• We store visited countries, biomes, realms, and ecoregions in your user profile (no GPS or exact location data)\\n• Location data is only sent to external services when certain features are used:\\n  - Google Maps, Places & Geocoding APIs: Maps, autocomplete & POI search\\n  - Mapbox: Map styles, tiles and navigation (Premium users)\\n  - OpenStreetMap (OSM): POI search and map data\\n  - GBIF: Query animals & plants in your region\\n  - OpenWeather & RainViewer: Weather and radar data\\n  - Open Elevation & OpenTopo: Terrain analysis\\n  - Google Gemini & OpenAI: AI features (e.g., quiz, adventure mode)\\n\\n### 💾 Firebase for Storage & Authentication\\n\\n• We use Firebase (Frankfurt region) for user authentication and data storage\\n\\n• Data such as user accounts, posts, comments, uploads, and visited regions are stored in Firebase\\n\\n• Firebase implements its own security and access controls to protect your data\\n\\n• You can request complete deletion of your account and associated data at any time\\n\\n### 📊 PostHog Analytics & App Usage\\n\\n• We use PostHog for anonymized usage statistics\\n\\n• PostHog helps us understand and improve app usage\\n\\n• Data collected includes: screens visited, app interactions, session duration\\n\\n• No personal data is linked to your account\\n\\n• You can disable tracking at any time in the settings\\n\\n### 👤 User Account & Profile Data\\n\\n• Registration required\\n\\n• Storage of: username, email address, premium status\\n\\n• Passwords are stored encrypted\\n\\n### 📤 Uploads & Interactions\\nData is only stored in the cloud when you:\\n\\n• Share an image or video: Username, date & location of capture\\n\\n• Create a post: Text is stored, but not your location\\n\\n• Like or comment: Only the interaction itself is stored\\n\\n### 🎥 Third-Party Services & APIs\\n\\n• Maps & Location: Google Maps, Places, Geocoding APIs, and Mapbox (Premium users)\\n\\n• Nature Data: GBIF for species information, PlantNet for plant identification\\n\\n• Weather: OpenWeather and RainViewer for weather data\\n\\n• Terrain: Open Elevation and OpenTopo for elevation data\\n\\n• Content: YouTube videos, Wikipedia/Wikimedia articles and images\\n\\n• AI Services: Google Gemini and OpenAI for interactive features\\n\\n• Each service processes data according to their own privacy policies\\n\\n• Premium features use RevenueCat for payment processing\\n\\n### 📺 YouTube API Services Usage\\nOur application uses YouTube API Services to provide you with video content related to outdoor activities, nature, and survival skills. By using our Media Feed feature, you acknowledge and agree to be bound by the YouTube Terms of Service (https://www.youtube.com/t/terms) and Google\'s Privacy Policy (http://www.google.com/policies/privacy).\\n\\n#### Data Collection and Access\\nWhen you use our Media Feed feature, we access and collect the following information through YouTube API Services:\\n\\nFrom YouTube API:\\n\\n• Public video metadata including titles, descriptions, thumbnails, channel names, and publication dates\\n• Video URLs and identifiers\\n• Search results based on your location and selected content categories\\n\\nFrom Your Device:\\n\\n• Your location data (when location-based feeds are enabled) to provide geographically relevant video content\\n• App preferences and settings stored locally on your device\\n• Cached video data stored temporarily in your device\'s local storage\\n\\n#### Data Storage and Caching\\n\\n• Video metadata retrieved from YouTube API is cached locally on your device for up to 24 hours to improve app performance and reduce data usage\\n\\n• Cached data includes video details, timestamps, selected categories, location scope, and location information\\n\\n• No user authentication data or personal YouTube account information is stored\\n\\n• All cached data is stored locally on your device using AsyncStorage and is not transmitted to external servers\\n\\n#### Data Usage and Processing\\nWe use the collected information to:\\n\\n• Display relevant outdoor and nature-related video content in our Media Feed\\n\\n• Provide location-based video recommendations when you enable location feeds\\n\\n• Cache content locally to improve app performance and offline capability\\n\\n• Filter and sort video results based on your preferences and location\\n\\n#### Data Sharing and Third Parties\\n\\n• We do not share any user data or YouTube API data with third parties for commercial purposes\\n\\n• Video interactions within embedded YouTube players are subject to YouTube\'s own privacy practices and may be tracked by Google/YouTube\\n\\n• Our app uses its own YouTube API credentials and does not access your personal YouTube account\\n\\n• Location data used for video searches is processed locally and combined with public search terms\\n\\n#### Cookies and Device Information\\n\\n• When viewing embedded YouTube videos, YouTube may place cookies or similar technologies on your device in accordance with Google\'s privacy practices\\n\\n• Our app accesses local device storage (AsyncStorage) to cache video content and store user preferences\\n\\n• We may collect device information necessary for app functionality, including location data for location-based features\\n\\n#### Data Retention\\n\\n• Locally cached video metadata is automatically deleted after 24 hours\\n\\n• User preferences and settings remain stored locally until you uninstall the app or manually clear app data\\n\\n• No YouTube API data is permanently stored on external servers\\n\\n#### User Rights and Control\\nYou can:\\n\\n• Disable location-based video feeds in app settings\\n• Clear cached data by refreshing the Media Feed or clearing app storage\\n• Access YouTube videos directly through the YouTube app or website where Google\'s privacy controls apply\\n• Contact us to request information about data collected through our app\\n\\n#### Third-Party Privacy Policies\\nBy using YouTube API Services within our app, you are also subject to:\\n\\n• Google Privacy Policy: http://www.google.com/policies/privacy\\n• YouTube Terms of Service: https://www.youtube.com/t/terms\\n\\n### 🤖 AI Consent\\nCertain features of this app use AI services provided by OpenAI and/or Google Gemini. These services may process user input outside the EU. No AI features are enabled by default. By explicitly activating AI features in the app, you provide your consent under Art. 6(1)(a) GDPR. You can withdraw this consent at any time via the app settings.\\n\\n## 3. Why Do We Process Your Data?\\nLegal bases according to GDPR:\\n\\n• Art. 6(1)(a) (Consent): Location sharing, AI usage, uploads\\n\\n• Art. 6(1)(b) (Contract fulfillment): User account & premium membership\\n\\n• Art. 6(1)(f) (Legitimate interest): App improvement through PostHog analytics\\n\\n## 4. Storage & Data Deletion\\nWhere is your data stored?\\n\\n• Location data: Local, not permanently stored\\n\\n• Posts, likes, uploads: In Firebase (Frankfurt region), if actively shared\\n\\n• Analytics data: Anonymized via PostHog\\n\\n• Most application data is stored locally on your device\\n\\n• Backend servers: Located in US and Europe (Heroku)\\n\\n• Plant identification: PlantNet API (external service)\\n\\n• News feed: Google News API\\n\\n• Payment processing: RevenueCat (no direct storage of payment data)\\n\\nData deletion:\\n\\n• All data can be deleted in app settings\\n\\n• Account deletion removes all linked data in Firebase\\n\\n## 5. Who Has Access to Your Data?\\n\\n• No sharing for advertising purposes\\n\\n• Location data only temporarily sent to external services\\n\\n• YouTube & Wikimedia collect their own data when used\\n\\n• PostHog processes anonymous usage statistics\\n\\n• Google APIs are used for various functions\\n\\n• No storage of payment data (Google Play / Apple Pay)\\n\\n## 6. Your Rights Under GDPR\\n\\n• Information about stored data\\n\\n• Correction of incorrect data\\n\\n• Deletion of your data\\n\\n• Data portability\\n\\n• Withdrawal of consent at any time\\n\\n📧 Contact for privacy questions: duselkay@gmail.com\\n\\n## 1. Responsible Party\\nDustin Keßler\\nAddress: Kurt Schumacher Straße 93, 46539 Dinslaken\\nEmail: duselkay@gmail.com"},"TermsPage":{"title":"Terms of Use","content":"# Terms of Use\\n\\nLast Updated: March 06, 2025\\n\\n## 1. General\\nThese Terms of Use govern the use of the Wildscope app. By creating an account, you agree to these terms. Minimum age for use is 16 years. The app provides wildlife tracking, plant identification, and nature exploration features designed to enhance your outdoor experience.\\n\\n## 2. App Features\\nWildscope provides location-based data for animals, plants, points of interest, and weather information. The app includes AI-powered features such as nature quizzes and adventure mode, the ability to upload photos and videos, create posts, and access premium features for additional content and enhanced functionality.\\n\\n## 3. User Account & Responsibility\\nYou are responsible for maintaining the security of your account and using a secure password. Users must comply with all applicable laws and regulations when using the app.\\n\\n### Prohibited Content\\nUsers are prohibited from posting illegal, offensive, or copyrighted content. Manipulation of location data is strictly forbidden. Account deletion is available at any time through the app settings.\\n\\n## 4. Technical Data Management\\nMost data is stored locally on your device for optimal performance and privacy. Firebase is used for authentication and cloud storage when necessary. PostHog provides anonymized usage analytics to improve the app. Google APIs enable various app functions. We do not use your data for advertising purposes.\\n\\n## 5. Premium Membership\\nPremium features are available through Google Play or Apple Pay. There is no right of withdrawal after using premium features. Premium subscriptions can be canceled at any time through your respective app store.\\n\\n## 6. Disclaimer\\n### Limitation of Liability\\nWe assume no liability for:\\n• Incorrect or outdated information about plants, animals, or points of interest\\n• Damage resulting from incorrect application of survival tips or nature-related information\\n• Loss of data, app malfunctions, or temporary unavailability of features\\n• Data security breaches resulting from third-party providers\\n• AI-generated content and decisions based on it — all AI outputs (text, images, audio, suggestions) are generated without guarantees of accuracy, safety, or appropriateness. Use at your own risk, especially in emergency or survival situations.\\n\\n### AI Content & Survival Use\\nWildscope includes experimental AI-powered features provided by third-party services such as OpenAI and Google Gemini. These features may generate inaccurate, misleading, or inappropriate content. Do not rely on AI-generated content for emergencies, survival, or safety-critical decisions. We disclaim all liability for outcomes resulting from decisions based on AI content.\\n\\n## 7. Content Rights\\n### User-Generated Content\\nAll uploads and user-generated content remain the property of the user. Content is private by default unless explicitly shared. Illegal content will be removed without notice.\\n\\n### App Content & Copyright\\nAll app content including data, texts, and graphics is protected by copyright. Commercial use of app content is strictly prohibited without written permission.\\n\\n## 8. YouTube Integration\\nOur application integrates with YouTube API Services to provide video content. Your use of any YouTube-related features is subject to the YouTube Terms of Service (https://www.youtube.com/t/terms), which are incorporated by reference into these Terms of Use.\\n\\n### Acceptable Use\\nWhen using our Media Feed feature, you agree to:\\n• Comply with YouTube\'s Terms of Service and Community Guidelines\\n• Use the video content for personal, non-commercial purposes only\\n• Not attempt to download, extract, or redistribute YouTube content outside of the intended app functionality\\n• Respect the intellectual property rights of video creators and YouTube\\n\\n### YouTube Disclaimer\\n• We are not responsible for the accuracy, legality, or appropriateness of YouTube content displayed in our app\\n• Video content is provided by third-party creators and does not necessarily reflect our views or opinions\\n• YouTube content availability and functionality may change without notice due to YouTube policy or technical changes\\n\\n### Data Processing Agreement\\nBy using YouTube API Services through our app, you acknowledge that:\\n• Google/YouTube may process your interaction data according to their privacy policies\\n• Embedded video players may collect analytics and usage data directly through YouTube\'s systems\\n• We act as a data processor for YouTube API data and do not control YouTube\'s data practices\\n\\n## 9. Refunds\\nAll payments are handled via Google Play or Apple App Store. We comply with their respective refund policies.\\n\\nWe do **not** offer refunds for cases including:\\n• AI or media features being unavailable due to quota exhaustion\\n• Temporary issues caused by third-party API outages\\n• Incompatibility with the user\'s device or lack of internet access\\n\\nUsers are responsible for canceling subscriptions via their respective store before renewal. We are unable to intervene in platform-based billing systems.\\n\\n## 10. Third-Party Services & API Limitations\\nWildscope relies on third-party APIs and platforms to provide many of its features. These services are subject to rate limits, outages, and usage restrictions — which may affect both free and premium users.\\n\\n**External services include:**\\n• Google APIs (Maps, Places, Geocoding, Static Maps)\\n• Mapbox (Tiles, Styles, Navigation)\\n• PlantNet (Plant identification)\\n• YouTube Data API\\n• Wikipedia / Wikimedia APIs\\n• OpenStreetMap / Overpass\\n• GBIF (Global Biodiversity)\\n• RainViewer & OpenWeatherMap (Weather & radar)\\n• Open Elevation & OpenTopo\\n• RevenueCat (in-app payment management)\\n• Firebase (auth, cloud, Firestore)\\n• OpenAI & Google Gemini (AI services)\\n\\nWildscope is not responsible for interruptions, degraded performance, or feature limitations caused by third-party service constraints. Examples:\\n• PlantNet free tier is limited to 500 identifications/day\\n• OpenAI or Gemini access may become unavailable due to quota or cost caps\\n• Mapbox features may be restricted once monthly tile limits are reached\\n\\n## 11. Legal Notes\\n• Wildscope does not guarantee the accuracy, completeness, or reliability of any content, recommendation, or advice\\n• All app features — including AI, maps, identification tools — are for informational and entertainment purposes only\\n• Wildscope is not a certified emergency or medical tool and should not be relied upon as such\\n• Users are responsible for complying with local regulations when using features involving species data, geolocation, or content sharing\\n\\n## 12. Changes to Terms of Use\\nContinued use of the app after updates to these terms implies acceptance of the new version. Users will be notified of material changes via app notifications or email.\\n\\n## 13. Contact\\nFor support or questions about these terms, contact us at: duselkay@gmail.com"},"ContactPage":{"title":"Contact Us","contact_intro":"Feel free to get in touch with us for any questions, feedback, or inquiries.","contact_person":"Contact Person","country":"Germany"},"NotFound":{"title":"Page Not Found","description":"Sorry, the page you are looking for does not exist or has been moved.","backHome":"Back to Homepage"},"General":{"loading":"Loading...","comingSoon":"Coming Soon"},"FAQ":{"title":"Frequently Asked Questions About Wildlife Tracking","question1":"How does Wildscope compare to other nature identification apps like iNaturalist?","answer1":"While iNaturalist focuses primarily on species identification and citizen science, Wildscope offers a complete outdoor experience with additional features specifically designed for nature enthusiasts. Our app includes offline wildlife identification, GPS navigation tools for wilderness exploration, interactive learning through nature quizzes, and an AI companion that understands your environment to provide personalized guidance—making it perfect for both casual nature lovers and serious wildlife trackers.","question2":"Can I identify plants and animals offline with Wildscope?","answer2":"Partially. The AI analysis requires an internet connection, but you\'ll see all tracked species from your area displayed and can use these to help with identification.","question3":"Which devices support the Wildscope nature exploration app?","answer3":"Wildscope\'s wildlife tracking and nature identification features are available for both iOS (iPhone/iPad) and Android devices through the App Store and Google Play Store, making it accessible for virtually all smartphone users.","question4":"Is Wildscope wildlife identification app free to use?","answer4":"Wildscope offers a free version with essential wildlife identification and nature exploration features. Our premium subscription unlocks advanced capabilities like unlimited species findings, more credits, more custom places to visit, and additional benefits. Check the app for current subscription options.","question5":"How accurate is Wildscope\'s plant and animal identification?","answer5":"Wildscope combines location data with advanced AI technology to identify wildlife and plants with high accuracy. While our recognition system continuously improves, identification accuracy varies by species, image quality, and viewing angle. We\'re constantly enhancing our algorithms through regular updates to provide increasingly accurate wildlife and plant identification in all environments.","question6":"Can I contribute to Wildscope\'s wildlife database?","answer6":"Absolutely! Wildscope thrives on community contributions. Your wildlife observations and plant identifications are securely added to our ecosystem database, improving the app\'s accuracy for everyone. This collaborative approach creates a comprehensive wildlife identification resource that benefits all nature enthusiasts.","question7":"Is Wildscope developed by a large tech company?","answer7":"No, Wildscope is an independent project developed by a dedicated nature enthusiast. The app is designed and maintained by a single passionate developer who prioritizes accuracy and user experience over monetization. This independent approach ensures that Wildscope remains true to its core mission: helping people connect with and understand nature without compromising user privacy or experience."},"OfflineCapabilities":{"title":"Offline Capabilities – Explore Without Limits","intro":"Once you\'ve loaded an area, you can enjoy full exploration even without internet access:","capability1":"Offline Maps & Trails","capability2":"Local Species Data & Natural Landmarks","capability3":"POIs and Community-Added Highlights","libraries_title":"Knowledge Libraries:","library1":"Edible Plants","library2":"Navigation Techniques","library3":"First Aid Basics","library4":"Shelter Building","library5":"Fire & Water Guides","library6":"Compass, Morse Tool, and more","library7":"Basic Nature Quizzes"},"OnlineFeatures":{"title":"Online Features – Enhanced by AI","intro":"Stay connected for the full experience:","feature1_title":"Wildscope Coach","feature1_desc":"Ask about your surroundings, upload images, and get personalized guidance.","feature2_title":"AI-Powered Identification","feature2_desc":"Instantly recognize species using photos and access in-depth, location-aware information.","feature3_title":"Smart Insights","feature3_desc":"Learn local history, community findings, seasonal patterns, and more.","feature4_title":"Global Community & Sharing","feature4_desc":"Share your discoveries, track rare sightings, and explore user-curated paths.","feature5_title":"Location-Based Quizzes & Text Adventures","feature5_desc":"Engage with your environment through rich, immersive experiences."},"Audience":{"title":"Who is Wildscope For?","intro":"Whether you\'re a seasoned explorer or just starting your nature journey, Wildscope is designed for you:","audience1_title":"Hikers & Trekkers","audience1_desc":"Navigate trails, identify species, and stay safe with offline maps and survival tools.","audience2_title":"Wildlife Photographers & Birdwatchers","audience2_desc":"Discover, track, and identify elusive species to capture that perfect shot.","audience3_title":"Families & Casual Explorers","audience3_desc":"Turn park visits into exciting learning adventures for all ages.","audience4_title":"Educators & Students","audience4_desc":"A powerful tool for outdoor education, biodiversity projects, and nature studies.","audience5_title":"Survivalists & Bushcrafters","audience5_desc":"Hone your skills with plant identification, shelter building guides, and offline resources.","conclusion":"And anyone with a curiosity for the natural world!"},"Testimonials":{"title":"What Our Explorers Say","testimonial1":"Wildscope has completely changed how I explore. The offline maps are a lifesaver, and the AI identification is incredibly accurate!","testimonial1_author":"Sarah L.","testimonial1_role":"Hiking Enthusiast","testimonial2":"As a biology teacher, this app is a fantastic tool for my students. It makes learning about local flora and fauna so much more interactive.","testimonial2_author":"David K.","testimonial2_role":"Educator"},"Pricing":{"title":"Choose Your Wildscope Plan","free_title":"Basic Explorer","free_subtitle":"Start your journey with essential features.","free_price":"Free","free_price_suffix":"Forever","free_feature1":"AI Species Identification (limited)","free_feature2":"Offline Regional Maps (1 region)","free_feature3":"Basic Survival Guide Access","free_feature4":"Community Forum Access","free_feature5":"Track 5 Favorite POIs","free_feature_limited1":"Ad-Supported Experience","free_cta":"Included with Download","pro_badge":"Best Value","pro_title":"Wildscope Pro","pro_subtitle":"Unlock the full power of nature exploration.","pro_price":"$2.99","pro_price_suffix":"per month (or $17.99/year)","pro_feature1":"Unlimited AI Species Identification","pro_feature2":"Unlimited Offline Regional Maps","pro_feature3":"Full Survival Guide & Advanced Tools","pro_feature4":"Premium Community Features","pro_feature5":"Track Unlimited Favorite POIs","pro_feature6":"Ad-Free Experience","pro_feature7":"Priority Support","pro_cta":"Go Pro & Explore More","footnote":"Prices may vary by region. Subscriptions managed through App Store/Google Play."}}');

